import { useMemo, useState } from "react";
import {
  Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, BriefcaseBusiness,
  CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp,
  ClipboardCheck, Clock3, Command, CreditCard, FileText, Filter, FolderOpen,
  LayoutDashboard, Link2, ListChecks, Menu, MessageSquare, MoreHorizontal,
  PanelLeftClose, Plus, Search, Settings2, ShieldCheck, Sparkles, Users,
  Workflow, X, Zap,
  type LucideIcon,
} from "lucide-react";
import { toast } from "sonner";

import {
  Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { portalConfig, aiEmployees, leadRecords, customerRecords, approvalsSeed } from "@/lib/portal-config";

type PageId = "overview" | "workforce" | "sales" | "customers" | "marketing" | "accounting" | "documents" | "reports" | "integrations" | "settings" | "audit";

const navIcons: Record<PageId, LucideIcon> = {
  overview: LayoutDashboard, workforce: Workflow, sales: BriefcaseBusiness,
  customers: Users, marketing: Sparkles, accounting: CreditCard, documents: FolderOpen,
  reports: Activity, integrations: Link2, settings: Settings2, audit: ClipboardCheck,
};

const pageTitles: Record<PageId, string> = {
  overview: "Dashboard", workforce: "AI Workforce", sales: "Sales & Leads",
  customers: "Customers", marketing: "Marketing", accounting: "Accounting",
  documents: "Documents", reports: "Reports", integrations: "Integrations",
  settings: "Settings", audit: "Audit Log",
};

const pipelineStages = ["Prospecting", "Contacted", "Qualified", "Ongoing", "Closing", "Won", "Lost"] as const;
const approvalLabels: Record<string, string> = { Invoice: "Accounting", Campaign: "Campaign", Plan: "Operations" };

function initials(name: string) {
  return name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase();
}

function Pill({ children, tone = "neutral", dot = false, className = "" }: { children: React.ReactNode; tone?: string | undefined; dot?: boolean | undefined; className?: string | undefined }) {
  const toneClass: Record<string, string> = {
    neutral: "border-border bg-secondary text-secondary-foreground",
    green: "border-positive/20 bg-positive-subtle text-positive",
    blue: "border-info/20 bg-info-subtle text-info",
    amber: "border-warning/20 bg-warning-subtle text-warning",
    violet: "border-violet/20 bg-violet-subtle text-violet",
    red: "border-destructive/20 bg-destructive/10 text-destructive",
  };
  return <span className={`inline-flex items-center gap-1.5 whitespace-nowrap rounded-full border px-2.5 py-1 text-[11px] font-medium ${toneClass[tone] ?? toneClass["neutral"]} ${className}`}>{dot && <span className="size-1.5 rounded-full bg-current" />}{children}</span>;
}

function SectionTitle({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div><p className="mb-2 text-[11px] font-semibold uppercase tracking-[0.16em] text-primary">{eyebrow}</p><h1 className="font-display text-3xl font-semibold tracking-tight text-foreground sm:text-[34px]">{title}</h1><p className="mt-2 text-sm text-muted-foreground">{description}</p></div>{action}</div>;
}

function Panel({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return <section className={`rounded-lg border border-border/80 bg-card/80 shadow-[0_16px_44px_-36px_oklch(0_0_0/75%)] backdrop-blur-xl ${className}`}>{children}</section>;
}

function PanelHeading({ icon: Icon, label, note, action }: { icon: LucideIcon; label: string; note?: string; action?: React.ReactNode }) {
  return <div className="flex items-start justify-between gap-3 px-5 pt-5"><div className="flex min-w-0 items-start gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-md border border-border bg-surface-quiet text-muted-foreground"><Icon className="size-4" /></span><div className="min-w-0"><h2 className="text-sm font-semibold text-foreground">{label}</h2>{note && <p className="mt-1 text-xs text-muted-foreground">{note}</p>}</div></div>{action}</div>;
}

function MetricCard({ label, value, change, icon: Icon, tone = "green", footnote }: { label: string; value: string; change: string; icon: LucideIcon; tone?: string; footnote: string }) {
  const toneClass: Record<string, string> = { green: "bg-positive-subtle text-positive", blue: "bg-info-subtle text-info", violet: "bg-violet-subtle text-violet", amber: "bg-warning-subtle text-warning" };
  return <Panel className="relative overflow-hidden p-4 sm:p-5"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="text-xs text-muted-foreground">{label}</p><p className="mt-3 font-display text-2xl font-semibold tracking-tight text-foreground sm:text-[28px]">{value}</p></div><span className={`grid size-9 shrink-0 place-items-center rounded-md ${toneClass[tone]}`}><Icon className="size-4" /></span></div><div className="mt-3 flex flex-wrap items-center gap-2"><Pill tone="green"><ArrowUpRight className="size-3" />{change}</Pill><span className="text-[11px] text-muted-foreground">{footnote}</span></div></Panel>;
}

function Avatar({ name, tone = "green", size = "md" }: { name: string; tone?: string; size?: "sm" | "md" | "lg" }) {
  const colors: Record<string, string> = { green: "bg-positive-subtle text-positive", blue: "bg-info-subtle text-info", violet: "bg-violet-subtle text-violet", amber: "bg-warning-subtle text-warning" };
  const sizes = { sm: "size-7 text-[9px]", md: "size-9 text-[11px]", lg: "size-12 text-xs" };
  return <span className={`inline-grid shrink-0 place-items-center rounded-full font-semibold ${colors[tone] ?? colors["green"]} ${sizes[size]}`}>{initials(name)}</span>;
}

function DataTable({ headers, children }: { headers: string[]; children: React.ReactNode }) {
  return <div className="overflow-x-auto"><table className="w-full min-w-[650px] border-collapse text-left"><thead><tr className="border-y border-border/80 bg-surface-quiet/60">{headers.map((header) => <th key={header} className="px-5 py-3 text-[10px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">{header}</th>)}</tr></thead><tbody className="divide-y divide-border/60">{children}</tbody></table></div>;
}

function ActivityRows({ items }: { items: { icon: LucideIcon; text: React.ReactNode; time: string; tone?: string | undefined }[] }) {
  const toneClass: Record<string, string> = { green: "text-positive bg-positive-subtle", blue: "text-info bg-info-subtle", amber: "text-warning bg-warning-subtle", violet: "text-violet bg-violet-subtle" };
  return <div className="divide-y divide-border/60">{items.map((item, index) => <div key={`${item.time}-${index}`} className="flex items-start gap-3 px-5 py-3.5"><span className={`mt-0.5 grid size-8 shrink-0 place-items-center rounded-full ${toneClass[item.tone ?? "green"]}`}><item.icon className="size-3.5" /></span><div className="min-w-0 flex-1 text-xs leading-5 text-foreground">{item.text}<p className="mt-0.5 text-[11px] text-muted-foreground">Today · {item.time}</p></div></div>)}</div>;
}

function WorkspaceSidebar({ active, onNavigate, collapsed, onCollapse, mobile = false, onClose }: { active: PageId; onNavigate: (page: PageId) => void; collapsed: boolean; onCollapse?: () => void; mobile?: boolean; onClose?: () => void }) {
  const main = portalConfig.modules.slice(0, 9);
  const admin = portalConfig.modules.slice(9);
  const items = (list: typeof main) => list.map((module) => {
    const Icon = navIcons[module.id as PageId];
    const selected = active === module.id;
    return <Button key={module.id} variant="ghost" title={module.label} aria-label={module.label} aria-current={selected ? "page" : undefined} onClick={() => { onNavigate(module.id as PageId); onClose?.(); }} className={`group relative h-9 w-full justify-start gap-3 rounded-md px-3 text-[13px] font-medium ${collapsed && !mobile ? "justify-center px-0" : ""} ${selected ? "bg-primary/10 text-primary hover:bg-primary/15 hover:text-primary" : "text-muted-foreground hover:bg-accent/70 hover:text-foreground"}`}><Icon className="size-[17px] shrink-0" />{(!collapsed || mobile) && <span className="truncate">{module.label}</span>}{selected && !collapsed && !mobile && <span className="ml-auto size-1.5 rounded-full bg-primary" />}</Button>;
  });
  return <aside className={`flex h-full flex-col border-r border-border/80 bg-surface-quiet/85 ${mobile ? "w-full" : collapsed ? "w-[72px]" : "w-[248px]"}`}>
    <div className={`flex h-[68px] shrink-0 items-center border-b border-border/80 px-4 ${collapsed && !mobile ? "justify-center" : "justify-between"}`}><div className="flex min-w-0 items-center gap-3"><div className="grid size-9 shrink-0 place-items-center rounded-md bg-primary text-primary-foreground shadow-[0_0_22px_-8px_var(--primary)]"><Zap className="size-[18px] fill-current" /></div>{(!collapsed || mobile) && <div className="min-w-0"><p className="truncate font-display text-[15px] font-semibold tracking-tight text-foreground">{portalConfig.company.name}<span className="text-primary">.</span></p><p className="text-[10px] text-muted-foreground">{portalConfig.company.descriptor}</p></div>}</div>{mobile ? <Button variant="ghost" size="icon" onClick={onClose} aria-label="Close navigation"><X /></Button> : !collapsed && <Button variant="ghost" size="icon" className="size-8 text-muted-foreground" onClick={onCollapse} aria-label="Collapse sidebar" title="Collapse sidebar"><PanelLeftClose className="size-4" /></Button>}</div>
    <div className="px-3 pt-5"><p className={`mb-2 px-3 text-[10px] font-semibold uppercase tracking-[0.15em] text-muted-foreground/70 ${collapsed && !mobile ? "sr-only" : ""}`}>Workspace</p><nav className="space-y-1">{items(main)}</nav></div>
    <div className="mt-6 px-3"><p className={`mb-2 px-3 text-[10px] font-semibold uppercase tracking-[0.15em] text-muted-foreground/70 ${collapsed && !mobile ? "sr-only" : ""}`}>Administration</p><nav className="space-y-1">{items(admin)}</nav></div>
    <div className="mt-auto p-3"><div className={`rounded-lg border border-border/80 bg-card/80 p-3 ${collapsed && !mobile ? "hidden" : ""}`}><div className="flex items-center gap-2"><ShieldCheck className="size-4 text-positive" /><span className="text-xs font-medium text-foreground">Workspace protected</span></div><p className="mt-1.5 text-[10px] leading-4 text-muted-foreground">AI actions with business impact wait for your approval.</p><Button variant="link" className="mt-1 h-auto p-0 text-[10px] text-info" onClick={() => onNavigate("settings")}>Review safeguards <ArrowRight className="size-3" /></Button></div><div className={`mt-3 flex items-center gap-2 rounded-md px-2 py-2 ${collapsed && !mobile ? "justify-center" : ""}`}><Avatar name="Alex Morgan" tone="blue" size="sm" />{(!collapsed || mobile) && <div className="min-w-0 flex-1"><p className="truncate text-xs font-medium text-foreground">Alex Morgan</p><p className="text-[10px] text-muted-foreground">Workspace owner</p></div>}{(!collapsed || mobile) && <MoreHorizontal className="size-4 text-muted-foreground" />}</div></div>
  </aside>;
}

function MiniBarChart({ values, color = "bg-primary", height = "h-28" }: { values: number[]; color?: string; height?: string }) {
  return <div className={`flex ${height} items-end gap-1.5`} aria-label="Weekly activity bar chart">{values.map((value, index) => <div key={index} className="group flex h-full flex-1 items-end"><div className={`w-full rounded-t-[3px] ${color} ${index === values.length - 2 ? "opacity-100" : "opacity-35"} transition-opacity group-hover:opacity-100`} style={{ height: `${value}%` }} /></div>)}</div>;
}

function Dashboard({ approvals, onApprove, onEmployee, onNavigate }: { approvals: typeof approvalsSeed; onApprove: (id: number) => void; onEmployee: (id: string) => void; onNavigate: (page: PageId) => void }) {
  const activity = [
    { icon: Check, text: <><strong className="font-medium">Saun</strong> resolved an onboarding question</>, time: "9:21 am", tone: "green" },
    { icon: Users, text: <><strong className="font-medium">Cathy</strong> qualified 3 new website leads</>, time: "9:17 am", tone: "blue" },
    { icon: FileText, text: <><strong className="font-medium">Jenny</strong> prepared invoice INV-2048</>, time: "9:12 am", tone: "amber" },
    { icon: ListChecks, text: <><strong className="font-medium">John</strong> reviewed team priorities</>, time: "8:56 am", tone: "violet" },
  ];
  return <div className="space-y-5">
    <div className="relative overflow-hidden rounded-lg border border-border/80 bg-surface-quiet p-5 sm:p-7"><div className="workspace-grid pointer-events-none absolute inset-0 opacity-40"/><div className="relative flex flex-wrap items-end justify-between gap-5"><div><div className="mb-3 flex items-center gap-2"><span className="size-1.5 rounded-full bg-primary shadow-[0_0_10px_var(--primary)]"/><span className="text-[11px] font-medium uppercase tracking-[0.12em] text-primary">Thursday, October 16, 2025</span><Pill>Demo workspace</Pill></div><h1 className="max-w-2xl font-display text-3xl font-semibold leading-tight tracking-tight text-foreground sm:text-[38px]">Good morning, Alex<span className="text-primary">.</span></h1><p className="mt-2 max-w-lg text-sm leading-6 text-muted-foreground">Here’s what’s moving across your business today. You have <span className="font-medium text-foreground">{approvals.length} items</span> ready for your review.</p></div><div className="flex gap-2"><Button variant="outline" className="border-border bg-card/70" onClick={() => onNavigate("reports")}><CalendarDays className="size-4" />This week</Button><Button onClick={() => onNavigate("workforce")}><Plus className="size-4" />Review team</Button></div></div></div>
    <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Pipeline value" value="$284,600" change="12.8%" icon={BriefcaseBusiness} footnote="vs. last month"/><MetricCard label="Active customers" value="1,284" change="8.2%" icon={Users} tone="blue" footnote="vs. last month"/><MetricCard label="Open opportunities" value="48" change="6.4%" icon={Workflow} tone="violet" footnote="across 7 stages"/><MetricCard label="Tasks completed" value="94.2%" change="3.1%" icon={ListChecks} tone="amber" footnote="AI team this week"/></div>
    <div className="grid grid-cols-1 gap-4 xl:grid-cols-[1.55fr_1fr]">
      <Panel className="overflow-hidden"><PanelHeading icon={Activity} label="Business overview" note="Performance at a glance" action={<Button variant="ghost" size="icon" aria-label="More business overview options"><MoreHorizontal className="size-4"/></Button>}/><div className="px-5 pb-5 pt-5"><div className="mb-5 flex flex-wrap items-end justify-between gap-4"><div><p className="text-2xl font-semibold text-foreground">$86,420 <span className="text-sm font-normal text-muted-foreground">revenue this month</span></p><p className="mt-1 text-xs text-muted-foreground"><span className="text-positive">↑ 14.6%</span> from previous month</p></div><div className="flex items-center gap-4 text-[10px] text-muted-foreground"><span className="flex items-center gap-1.5"><i className="size-1.5 rounded-full bg-primary"/>This month</span><span className="flex items-center gap-1.5"><i className="size-1.5 rounded-full bg-info"/>Last month</span></div></div><div className="grid h-32 grid-cols-12 items-end gap-2 border-b border-border/70 pb-2">{[46, 63, 54, 77, 61, 88, 68, 74, 91, 70, 83, 95].map((height, i) => <div key={i} className="flex h-full items-end gap-0.5"><div className="w-1/2 rounded-t-[2px] bg-primary/75" style={{height: `${height}%`}}/><div className="w-1/2 rounded-t-[2px] bg-info/35" style={{height: `${Math.max(16, height - 18 + (i % 3) * 5)}%`}}/></div>)}</div><div className="mt-2 flex justify-between text-[10px] text-muted-foreground"><span>Oct 1</span><span>Oct 5</span><span>Oct 10</span><span>Oct 15</span><span>Oct 20</span><span>Oct 25</span><span>Oct 31</span></div></div></Panel>
      <Panel className="overflow-hidden"><PanelHeading icon={ShieldCheck} label="Approval queue" note="Human sign-off required" action={<Pill tone="amber">{approvals.length} pending</Pill>}/><div className="divide-y divide-border/60 px-5 pt-3">{approvals.length ? approvals.slice(0, 3).map((item) => <div key={item.id} className="flex items-center gap-3 py-3"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="truncate text-xs font-medium text-foreground">{item.title}</span></div><p className="mt-1 text-[11px] text-muted-foreground">{item.detail} · {item.time}</p></div><Button size="sm" variant="outline" className="h-7 shrink-0 px-2.5 text-[10px]" onClick={() => onApprove(item.id)}>Review</Button></div>) : <div className="py-7 text-center text-xs text-muted-foreground">No approvals waiting for you.</div>}</div><div className="px-5 pb-4 pt-2"><Button variant="link" className="h-auto p-0 text-xs text-info" onClick={() => onNavigate("audit")}>View approval history <ArrowRight className="size-3"/></Button></div></Panel>
    </div>
    <div className="grid grid-cols-1 gap-4 xl:grid-cols-[1.25fr_1fr_0.9fr]">
      <Panel className="overflow-hidden"><PanelHeading icon={Workflow} label="AI workforce" note="Team availability and workload" action={<Button variant="ghost" size="sm" className="h-8 text-xs text-info" onClick={() => onNavigate("workforce")}>View all <ArrowRight className="size-3"/></Button>}/><div className="divide-y divide-border/60 px-5 pt-2">{aiEmployees.map((employee) => <div key={employee.id} className="flex items-center gap-3 py-3"><Button variant="ghost" className="h-auto min-w-0 flex-1 justify-start gap-3 p-0 text-left hover:bg-transparent" onClick={() => onEmployee(employee.id)}><Avatar name={employee.name} tone={employee.tone} /><span className="min-w-0 flex-1"><span className="block text-xs font-semibold text-foreground">{employee.name}<span className="ml-2 font-normal text-muted-foreground">{employee.department}</span></span><span className="mt-1 block truncate text-[10px] text-muted-foreground">{employee.focus}</span></span></Button><Pill tone={employee.tone} dot>{employee.status}</Pill></div>)}</div></Panel>
      <Panel className="overflow-hidden"><PanelHeading icon={BriefcaseBusiness} label="Sales pipeline" note="48 opportunities · $284,600" action={<Button variant="ghost" size="icon" aria-label="Sales pipeline options"><MoreHorizontal className="size-4"/></Button>}/><div className="space-y-4 px-5 pb-5 pt-5">{[["Prospecting", 18, "bg-info"], ["Qualified", 14, "bg-primary"], ["Ongoing", 9, "bg-violet"], ["Closing", 7, "bg-warning"]].map(([name, amount, color]) => <div key={String(name)}><div className="mb-1.5 flex justify-between text-[11px]"><span className="text-muted-foreground">{name}</span><span className="text-foreground">{amount}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-secondary"><div className={`h-full rounded-full ${color}`} style={{width: `${Number(amount) * 4.6}%`}}/></div></div>)}<Button variant="link" className="h-auto p-0 text-xs text-info" onClick={() => onNavigate("sales")}>Open pipeline <ArrowRight className="size-3"/></Button></div></Panel>
      <Panel className="overflow-hidden"><PanelHeading icon={Activity} label="Recent activity" note="Across your workspace" action={<Button variant="ghost" size="icon" aria-label="Activity options"><MoreHorizontal className="size-4"/></Button>}/><div className="pt-2"><ActivityRows items={activity.slice(0, 3)}/></div><div className="px-5 pb-4"><Button variant="link" className="h-auto p-0 text-xs text-info" onClick={() => onNavigate("audit")}>Full audit log <ArrowRight className="size-3"/></Button></div></Panel>
    </div>
    <div className="grid grid-cols-1 gap-4 lg:grid-cols-2"><Panel className="overflow-hidden"><PanelHeading icon={Users} label="New leads" note="Your latest opportunities" action={<Button variant="ghost" size="sm" className="h-8 text-xs text-info" onClick={() => onNavigate("sales")}>All leads <ArrowRight className="size-3"/></Button>}/><DataTable headers={["Contact", "Source", "Stage", "Value"]}>{leadRecords.slice(0, 3).map((lead) => <tr key={lead.email}><td className="px-5 py-3"><div className="text-xs font-medium text-foreground">{lead.name}</div><div className="mt-0.5 text-[10px] text-muted-foreground">{lead.company}</div></td><td className="px-5 py-3 text-xs text-muted-foreground">{lead.source}</td><td className="px-5 py-3"><Pill tone={lead.stage === "Qualified" ? "blue" : "neutral"}>{lead.stage}</Pill></td><td className="px-5 py-3 text-xs font-medium text-foreground">{lead.value}</td></tr>)}</DataTable></Panel><Panel className="overflow-hidden"><PanelHeading icon={CreditCard} label="Accounting summary" note="October demo snapshot" action={<Button variant="ghost" size="sm" className="h-8 text-xs text-info" onClick={() => onNavigate("accounting")}>View details <ArrowRight className="size-3"/></Button>}/><div className="grid grid-cols-2 gap-px overflow-hidden rounded-md border border-border/70 bg-border/70 m-5"><div className="bg-card p-4"><p className="text-[11px] text-muted-foreground">Paid invoices</p><p className="mt-2 text-xl font-semibold text-foreground">$48,290</p><p className="mt-1 text-[10px] text-positive">18 transactions</p></div><div className="bg-card p-4"><p className="text-[11px] text-muted-foreground">Awaiting payment</p><p className="mt-2 text-xl font-semibold text-foreground">$12,840</p><p className="mt-1 text-[10px] text-warning">3 invoices due</p></div><div className="col-span-2 bg-card px-4 py-3"><div className="flex items-center justify-between text-[11px]"><span className="text-muted-foreground">Monthly target</span><span className="font-medium text-foreground">72% complete</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-secondary"><div className="h-full w-[72%] rounded-full bg-primary"/></div></div></div></Panel></div>
  </div>;
}

function WorkforcePage({ onEmployee }: { onEmployee: (id: string) => void }) {
  return <div><SectionTitle eyebrow="Your digital team" title="AI Workforce" description="Monitor your workforce, review work, and set clear boundaries." action={<Button onClick={() => toast.info("Your team is configured in workspace settings.")}><Plus className="size-4"/>Add employee</Button>}/><div className="mb-5 flex flex-wrap gap-2"><Pill tone="green" dot>2 active</Pill><Pill tone="blue" dot>1 working</Pill><Pill tone="amber" dot>1 needs approval</Pill><span className="ml-auto flex items-center gap-1.5 text-[11px] text-muted-foreground"><ShieldCheck className="size-3.5 text-positive"/>Approvals are required for consequential actions</span></div><div className="grid grid-cols-1 gap-4 xl:grid-cols-2">{aiEmployees.map((employee) => <Panel key={employee.id} className="overflow-hidden"><div className="flex flex-wrap items-start justify-between gap-4 border-b border-border/70 p-5"><div className="flex items-center gap-3"><Avatar name={employee.name} tone={employee.tone} size="lg"/><div><div className="flex flex-wrap items-center gap-2"><h2 className="font-display text-lg font-semibold text-foreground">{employee.name}</h2><Pill tone={employee.tone} dot>{employee.status}</Pill></div><p className="mt-1 text-xs text-muted-foreground">{employee.role}</p></div></div><Button variant="outline" size="sm" onClick={() => onEmployee(employee.id)}>Open profile <ArrowRight className="size-3.5"/></Button></div><div className="grid grid-cols-3 divide-x divide-border/70 border-b border-border/70"><div className="p-4"><p className="text-[10px] text-muted-foreground">Open tasks</p><p className="mt-1 text-lg font-semibold text-foreground">{employee.tasks}</p></div><div className="p-4"><p className="text-[10px] text-muted-foreground">Completed</p><p className="mt-1 text-lg font-semibold text-foreground">{employee.completed}</p></div><div className="p-4"><p className="text-[10px] text-muted-foreground">Quality score</p><p className="mt-1 text-lg font-semibold text-foreground">{employee.score}%</p></div></div><div className="grid grid-cols-1 gap-5 p-5 md:grid-cols-2"><div><p className="mb-3 text-[10px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">Responsibilities</p><ul className="space-y-2">{employee.responsibilities.slice(0, 4).map((task) => <li key={task} className="flex gap-2 text-[11px] leading-4 text-muted-foreground"><Check className="mt-0.5 size-3 shrink-0 text-positive"/>{task}</li>)}</ul></div><div><p className="mb-3 text-[10px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">Current focus</p><div className="rounded-md border border-border bg-surface-quiet p-3"><p className="text-xs font-medium text-foreground">{employee.focus}</p><p className="mt-1 text-[10px] text-muted-foreground">Work remains within configured permissions.</p></div><div className="mt-3 flex items-center justify-between text-[10px]"><span className="text-muted-foreground">Weekly task completion</span><span className="font-medium text-foreground">{employee.score}%</span></div><div className="mt-1.5 h-1 overflow-hidden rounded-full bg-secondary"><div className="h-full rounded-full bg-primary" style={{width: `${employee.score}%`}}/></div></div></div></Panel>)}</div><Panel className="mt-4"><PanelHeading icon={ShieldCheck} label="Workforce permissions" note="Choose which actions need your sign-off" action={<Button variant="outline" size="sm" onClick={() => toast.info("Permission controls are saved to this demo workspace.")}>Manage permissions <ArrowRight className="size-3.5"/></Button>}/><div className="grid gap-3 px-5 pb-5 pt-4 sm:grid-cols-3">{[{name:"Customer communication",help:"Draft freely · send after approval"},{name:"Financial actions",help:"Invoice and payment changes require approval"},{name:"External publishing",help:"Campaigns stay in review until approved"}].map((item) => <div key={item.name} className="rounded-md border border-border bg-surface-quiet p-3"><div className="flex items-center gap-2"><ShieldCheck className="size-3.5 text-positive"/><span className="text-xs font-medium text-foreground">{item.name}</span></div><p className="mt-1.5 text-[10px] leading-4 text-muted-foreground">{item.help}</p></div>)}</div></Panel></div>;
}

function SalesPage({ search }: { search: string }) {
  const [stage, setStage] = useState("All stages");
  const filtered = leadRecords.filter((lead) => (stage === "All stages" || lead.stage === stage) && `${lead.name} ${lead.company} ${lead.source} ${lead.email}`.toLowerCase().includes(search.toLowerCase()));
  const total = leadRecords.reduce((sum, lead) => sum + Number(lead.value.replace(/[$,]/g, "")), 0);
  return <div><SectionTitle eyebrow="Customer growth" title="Sales & Leads" description="Follow every opportunity from first contact through close." action={<Button onClick={() => toast.info("New lead form is ready to connect to your CRM.")}><Plus className="size-4"/>New lead</Button>}/><div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><MetricCard label="Open pipeline" value={`$${total.toLocaleString()}`} change="11.4%" icon={BriefcaseBusiness} footnote="vs. last month"/><MetricCard label="Active leads" value="42" change="8.2%" icon={Users} tone="blue" footnote="across all stages"/><MetricCard label="Qualified this month" value="18" change="14.0%" icon={Check} tone="violet" footnote="lead qualification"/><MetricCard label="Win rate" value="32.6%" change="4.1%" icon={ArrowUpRight} tone="amber" footnote="last 30 days"/></div><div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4 xl:grid-cols-7">{pipelineStages.map((item) => <button key={item} onClick={() => setStage(stage === item ? "All stages" : item)} className={`rounded-md border p-3 text-left transition-colors ${stage === item ? "border-primary/60 bg-primary/10" : "border-border bg-card/80 hover:bg-accent"}`}><p className="text-[10px] text-muted-foreground">{item}</p><p className="mt-1.5 font-display text-lg font-semibold text-foreground">{leadRecords.filter((lead) => lead.stage === item).length}</p></button>)}</div><Panel className="mt-4 overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 p-5"><div><h2 className="text-sm font-semibold text-foreground">Pipeline records <span className="ml-1 text-xs font-normal text-muted-foreground">{filtered.length} opportunities</span></h2><p className="mt-1 text-[11px] text-muted-foreground">Assigned AI team members can prepare actions; external follow-up awaits your approval.</p></div><div className="flex gap-2"><Button variant="outline" size="sm" onClick={() => setStage("All stages")}><Filter className="size-3.5"/>{stage}</Button><Button variant="outline" size="sm" onClick={() => toast.info("Lead list exported in this demo.")}><ArrowDownRight className="size-3.5"/>Export</Button></div></div><DataTable headers={["Contact", "Source", "Assigned to", "Stage", "Value", "Next action"]}>{filtered.map((lead) => <tr key={lead.email}><td className="px-5 py-3"><p className="text-xs font-medium text-foreground">{lead.name}</p><p className="mt-1 text-[10px] text-muted-foreground">{lead.company} · {lead.email}</p></td><td className="px-5 py-3 text-xs text-muted-foreground">{lead.source}</td><td className="px-5 py-3 text-xs text-foreground">{lead.employee}</td><td className="px-5 py-3"><Pill tone={lead.stage === "Closing" ? "amber" : lead.stage === "Won" ? "green" : lead.stage === "Qualified" ? "blue" : "neutral"}>{lead.stage}</Pill></td><td className="px-5 py-3 text-xs font-medium text-foreground">{lead.value}</td><td className="px-5 py-3 text-xs text-muted-foreground">{lead.next}</td></tr>)}</DataTable>{filtered.length === 0 && <p className="px-5 py-10 text-center text-sm text-muted-foreground">No leads match this search.</p>}</Panel></div>;
}

function CustomersPage({ search }: { search: string }) {
  const [selected, setSelected] = useState<(typeof customerRecords)[number] | null>(null);
  const [filter, setFilter] = useState("All customers");
  const filtered = customerRecords.filter((customer) => `${customer.name} ${customer.company} ${customer.email}`.toLowerCase().includes(search.toLowerCase()) && (filter === "All customers" || customer.status === filter));
  return <div><SectionTitle eyebrow="Relationships" title="Customers" description="Customer records, communication, and relationship history." action={<Button onClick={() => toast.info("New customer form is ready to connect to your CRM.")}><Plus className="size-4"/>Add customer</Button>}/><div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><MetricCard label="Total customers" value="1,284" change="8.2%" icon={Users} footnote="this month"/><MetricCard label="Active customers" value="1,106" change="6.8%" icon={Check} tone="blue" footnote="86% retention"/><MetricCard label="Onboarding" value="24" change="3.5%" icon={Workflow} tone="violet" footnote="in progress"/><MetricCard label="At-risk accounts" value="7" change="2.0%" icon={Clock3} tone="amber" footnote="need attention"/></div><Panel className="mt-4 overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 p-5"><div><h2 className="text-sm font-semibold text-foreground">Customer directory</h2><p className="mt-1 text-[11px] text-muted-foreground">Demo records · select a row to see customer history.</p></div><select value={filter} onChange={(event) => setFilter(event.target.value)} className="h-9 rounded-md border border-input bg-surface-quiet px-3 text-xs text-foreground"><option>All customers</option><option>Active customer</option><option>Onboarding</option></select></div><DataTable headers={["Customer", "Relationship", "AI owner", "Lifetime value", "Last interaction", "Details"]}>{filtered.map((customer) => <tr key={customer.email}><td className="px-5 py-3"><div className="flex items-center gap-3"><Avatar name={customer.name} tone="blue" size="sm"/><div><p className="text-xs font-medium text-foreground">{customer.name}</p><p className="mt-1 text-[10px] text-muted-foreground">{customer.company} · {customer.email}</p></div></div></td><td className="px-5 py-3"><Pill tone={customer.status === "Onboarding" ? "blue" : "green"}>{customer.status}</Pill></td><td className="px-5 py-3 text-xs text-foreground">{customer.owner}</td><td className="px-5 py-3 text-xs font-medium text-foreground">{customer.spend}</td><td className="px-5 py-3 text-xs text-muted-foreground">{customer.last}</td><td className="px-5 py-3"><Button variant="ghost" size="sm" onClick={() => setSelected(customer)}>Open profile <ArrowRight className="size-3"/></Button></td></tr>)}</DataTable>{filtered.length === 0 && <p className="px-5 py-10 text-center text-sm text-muted-foreground">No customers match this search.</p>}</Panel><Dialog open={selected !== null} onOpenChange={(open) => !open && setSelected(null)}><DialogContent className="border-border bg-card text-foreground"><DialogHeader><DialogTitle>Customer profile</DialogTitle><DialogDescription>Customer relationship history from this demo workspace.</DialogDescription></DialogHeader>{selected && <div className="space-y-4"><div className="flex items-center gap-3"><Avatar name={selected.name} tone="blue" size="lg"/><div><p className="font-semibold text-foreground">{selected.name}</p><p className="text-xs text-muted-foreground">{selected.company}</p></div></div><div className="grid grid-cols-2 gap-3"><div className="rounded-md border border-border bg-surface-quiet p-3"><p className="text-[10px] text-muted-foreground">Email</p><p className="mt-1 text-xs text-foreground">{selected.email}</p></div><div className="rounded-md border border-border bg-surface-quiet p-3"><p className="text-[10px] text-muted-foreground">AI relationship owner</p><p className="mt-1 text-xs text-foreground">{selected.owner}</p></div><div className="rounded-md border border-border bg-surface-quiet p-3"><p className="text-[10px] text-muted-foreground">Lifetime value</p><p className="mt-1 text-xs text-foreground">{selected.spend}</p></div><div className="rounded-md border border-border bg-surface-quiet p-3"><p className="text-[10px] text-muted-foreground">Last interaction</p><p className="mt-1 text-xs text-foreground">{selected.last}</p></div></div><div className="rounded-md border border-border p-4"><p className="text-xs font-medium text-foreground">Recent communication</p><p className="mt-2 text-xs leading-5 text-muted-foreground">Cathy prepared a follow-up summary for the account. External messages require approval before sending.</p></div></div>}</DialogContent></Dialog></div>;
}

function MarketingPage() {
  const campaigns = [{name:"October product update",channel:"Email",status:"In review",reach:"2,480",engagement:"8.4%",tone:"amber"},{name:"Studio stories · week 42",channel:"Instagram",status:"Scheduled",reach:"1,840",engagement:"6.2%",tone:"blue"},{name:"Founder notes · Q4",channel:"LinkedIn",status:"Draft",reach:"860",engagement:"4.8%",tone:"violet"}];
  return <div><SectionTitle eyebrow="Growth & content" title="Marketing" description="Campaign performance, content planning, and the approval queue." action={<Button onClick={() => toast.info("Campaign draft created in this demo.")}><Plus className="size-4"/>New campaign</Button>}/><div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><MetricCard label="Campaign reach" value="48.2K" change="18.6%" icon={Activity} footnote="this month"/><MetricCard label="Engagement rate" value="6.8%" change="0.9%" icon={ArrowUpRight} tone="blue" footnote="across channels"/><MetricCard label="Marketing leads" value="126" change="12.4%" icon={Users} tone="violet" footnote="campaign attributed"/><MetricCard label="Content awaiting review" value="3" change="1 new" icon={ClipboardCheck} tone="amber" footnote="human review required"/></div><div className="mt-4 grid gap-4 xl:grid-cols-[1.1fr_0.9fr]"><Panel className="overflow-hidden"><PanelHeading icon={Sparkles} label="Campaign performance" note="Reach and engagement · sample data"/><div className="px-5 pb-5 pt-5"><div className="flex items-end justify-between gap-2">{["Email","Instagram","LinkedIn","Website","WhatsApp","Facebook"].map((channel,i)=><div key={channel} className="flex flex-1 flex-col items-center gap-2"><div className="flex h-32 w-full items-end justify-center gap-1"><div className="w-2/5 rounded-t-sm bg-info/50" style={{height:`${[44,70,58,36,28,48][i]}%`}}/><div className="w-2/5 rounded-t-sm bg-primary" style={{height:`${[71,56,80,62,46,38][i]}%`}}/></div><span className="text-center text-[9px] text-muted-foreground">{channel}</span></div>)}</div><div className="mt-4 flex gap-4 text-[10px] text-muted-foreground"><span className="flex items-center gap-1.5"><i className="size-1.5 rounded-full bg-info"/>Reach</span><span className="flex items-center gap-1.5"><i className="size-1.5 rounded-full bg-primary"/>Engagement</span></div></div></Panel><Panel className="overflow-hidden"><PanelHeading icon={ClipboardCheck} label="Content approval queue" note="No publishing without your review" action={<Pill tone="amber">2 awaiting</Pill>}/><div className="space-y-3 p-5"><div className="rounded-md border border-border bg-surface-quiet p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-semibold text-foreground">October product update</p><p className="mt-1 text-[10px] text-muted-foreground">Email · Draft by Cathy · Today 9:08 am</p></div><Pill tone="amber">In review</Pill></div><p className="mt-3 text-xs leading-5 text-muted-foreground">A new season of thoughtful tools for the work you do every day…</p><div className="mt-3 flex justify-end gap-2"><Button variant="outline" size="sm" onClick={() => toast.info("Draft sent back to Cathy for revisions.")}>Request changes</Button><Button size="sm" onClick={() => toast.success("Demo draft approved and recorded in the audit log.")}>Approve draft</Button></div></div><div className="flex items-center gap-3 rounded-md border border-border bg-surface-quiet p-3"><Avatar name="Cathy" tone="violet" size="sm"/><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium text-foreground">Studio stories · week 42</p><p className="mt-1 text-[10px] text-muted-foreground">Instagram · Scheduled pending review</p></div><Button variant="ghost" size="sm" onClick={() => toast.info("Social post opened for review.")}>Review</Button></div></div></Panel></div><Panel className="mt-4 overflow-hidden"><PanelHeading icon={CalendarDays} label="Campaigns & content calendar" note="Upcoming work and campaign status" action={<Button variant="outline" size="sm" onClick={() => toast.info("Showing October content calendar.")}><CalendarDays className="size-3.5"/>October 2025</Button>}/><div className="p-5"><div className="mb-4 grid grid-cols-7 gap-2 text-center">{["M","T","W","T","F","S","S"].map((day,i)=><span key={`${day}-${i}`} className="text-[10px] font-medium text-muted-foreground">{day}</span>)}{Array.from({length:14},(_,i)=><div key={i} className={`grid aspect-square min-h-8 place-items-center rounded-md border text-[10px] ${i===9?"border-primary/40 bg-primary/10 text-primary":"border-border/70 bg-surface-quiet text-muted-foreground"}`}>{i+13}</div>)}</div><div className="space-y-2">{campaigns.map((item)=><div key={item.name} className="flex flex-wrap items-center gap-3 rounded-md border border-border bg-surface-quiet p-3"><span className="min-w-0 flex-1 text-xs font-medium text-foreground">{item.name}</span><span className="text-[10px] text-muted-foreground">{item.channel}</span><Pill tone={item.tone}>{item.status}</Pill><span className="text-[10px] text-muted-foreground">{item.reach} reach</span></div>)}</div></div></Panel></div>;
}

function AccountingPage() {
  const invoices = [{id:"INV-2048",customer:"Arc Studio",date:"Oct 16, 2025",amount:"$2,400",status:"Needs approval",tone:"amber"},{id:"INV-2047",customer:"Evergreen Group",date:"Oct 14, 2025",amount:"$4,800",status:"Paid",tone:"green"},{id:"INV-2046",customer:"Goodland Retail",date:"Oct 12, 2025",amount:"$1,850",status:"Pending",tone:"blue"},{id:"INV-2041",customer:"Coda Works",date:"Oct 02, 2025",amount:"$3,200",status:"Overdue",tone:"red"}];
  return <div><SectionTitle eyebrow="Finance administration" title="Accounting" description="Invoices, payment activity, and administrative financial overview." action={<Button onClick={() => toast.info("Invoice drafts must be reviewed before sending.")}><Plus className="size-4"/>Create invoice</Button>}/><div className="mb-4 flex items-start gap-2 rounded-md border border-warning/20 bg-warning-subtle p-3 text-xs text-warning"><CircleHelp className="mt-0.5 size-4 shrink-0"/><p>This is an administrative overview, not professional accounting software. Demo values are illustrative; financial actions require human sign-off.</p></div><div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><MetricCard label="Revenue collected" value="$48,290" change="14.6%" icon={CreditCard} footnote="this month"/><MetricCard label="Outstanding" value="$12,840" change="3 invoices" icon={Clock3} tone="amber" footnote="awaiting payment"/><MetricCard label="Overdue" value="$3,200" change="1 invoice" icon={ArrowDownRight} tone="violet" footnote="requires follow-up"/><MetricCard label="Expenses" value="$16,480" change="6.2%" icon={Activity} tone="blue" footnote="this month"/></div><Panel className="mt-4 overflow-hidden"><PanelHeading icon={FileText} label="Invoices" note="AI-prepared invoices remain drafts until approved" action={<Button variant="outline" size="sm" onClick={() => toast.info("Showing all invoice records.")}><Filter className="size-3.5"/>Filter</Button>}/><DataTable headers={["Invoice", "Customer", "Issue date", "Amount", "Status", "Action"]}>{invoices.map((invoice) => <tr key={invoice.id}><td className="px-5 py-3 text-xs font-medium text-foreground">{invoice.id}</td><td className="px-5 py-3 text-xs text-foreground">{invoice.customer}</td><td className="px-5 py-3 text-xs text-muted-foreground">{invoice.date}</td><td className="px-5 py-3 text-xs font-semibold text-foreground">{invoice.amount}</td><td className="px-5 py-3"><Pill tone={invoice.tone}>{invoice.status}</Pill></td><td className="px-5 py-3"><Button variant="ghost" size="sm" onClick={() => toast.info(`${invoice.id} opened in demo view.`)}>{invoice.status === "Needs approval" ? "Review" : "Details"}<ArrowRight className="size-3"/></Button></td></tr>)}</DataTable></Panel><div className="mt-4 grid gap-4 lg:grid-cols-2"><Panel className="overflow-hidden"><PanelHeading icon={Activity} label="Monthly summary" note="Revenue compared to expenses"/><div className="px-5 pb-5 pt-4"><MiniBarChart values={[40,56,50,68,63,82,71,91,75,87,94,80]} height="h-36"/><div className="mt-2 flex justify-between text-[10px] text-muted-foreground"><span>Jan</span><span>Mar</span><span>May</span><span>Jul</span><span>Sep</span><span>Oct</span></div></div></Panel><Panel className="overflow-hidden"><PanelHeading icon={ShieldCheck} label="AI accounting activity" note="Prepared by Jenny · October"/><ActivityRows items={[{icon:FileText,text:<><strong className="font-medium">Invoice INV-2048</strong> prepared for review</>,time:"9:28 am",tone:"amber"},{icon:Check,text:<>12 sample transactions categorized</>,time:"8:46 am",tone:"green"},{icon:Clock3,text:<>Payment mismatch flagged for review</>,time:"Yesterday",tone:"blue"}]}/></Panel></div></div>;
}

function DocumentsPage({ search }: { search: string }) {
  const documents = [{name:"October invoice batch",type:"Invoice",owner:"Jenny",date:"Oct 16, 2025",size:"2.4 MB",status:"Needs approval",tone:"amber"},{name:"Q4 campaign brief",type:"Marketing",owner:"Cathy",date:"Oct 15, 2025",size:"1.8 MB",status:"Draft",tone:"blue"},{name:"Customer onboarding guide",type:"Operations",owner:"John",date:"Oct 14, 2025",size:"860 KB",status:"Approved",tone:"green"},{name:"Technical setup notes",type:"Support",owner:"Saun",date:"Oct 12, 2025",size:"420 KB",status:"Reviewed",tone:"violet"}];
  const filtered = documents.filter((doc) => `${doc.name} ${doc.type} ${doc.owner}`.toLowerCase().includes(search.toLowerCase()));
  return <div><SectionTitle eyebrow="Workspace files" title="Documents" description="Find, organize, and review your business documents." action={<Button onClick={() => toast.info("Choose a file to upload when document storage is connected.")}><Plus className="size-4"/>Upload document</Button>}/><div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><MetricCard label="Total documents" value="248" change="12 new" icon={FileText} footnote="this month"/><MetricCard label="Needs approval" value="4" change="2 added" icon={ClipboardCheck} tone="amber" footnote="human review"/><MetricCard label="AI generated" value="36" change="8 new" icon={Sparkles} tone="violet" footnote="reviewed drafts"/><MetricCard label="Shared folders" value="12" change="3 active" icon={FolderOpen} tone="blue" footnote="workspace"/></div><div className="mt-4 grid gap-4 lg:grid-cols-[240px_1fr]"><Panel className="h-fit p-4"><h2 className="mb-3 text-xs font-semibold text-foreground">Folders</h2>{["All documents", "Invoices", "Marketing", "Operations", "Customer files", "AI drafts", "Needs approval"].map((folder,i)=><Button key={folder} variant="ghost" className={`mb-1 h-9 w-full justify-start gap-2 text-xs ${i===0?"bg-primary/10 text-primary":"text-muted-foreground"}`} onClick={() => toast.info(`${folder} selected.`)}><FolderOpen className="size-3.5"/>{folder}{i===6&&<Pill tone="amber">4</Pill>}</Button>)}</Panel><Panel className="overflow-hidden"><div className="flex items-center justify-between p-5"><div><h2 className="text-sm font-semibold text-foreground">Recent documents</h2><p className="mt-1 text-[11px] text-muted-foreground">Demo files · {filtered.length} results</p></div><Button variant="outline" size="sm" onClick={() => toast.info("Document filters opened.")}><Filter className="size-3.5"/>Filter</Button></div><DataTable headers={["Document", "Category", "Created by", "Date", "Size", "Status"]}>{filtered.map((doc)=><tr key={doc.name}><td className="px-5 py-3"><div className="flex items-center gap-2"><span className="grid size-8 place-items-center rounded-md bg-info-subtle text-info"><FileText className="size-4"/></span><span className="text-xs font-medium text-foreground">{doc.name}</span></div></td><td className="px-5 py-3 text-xs text-muted-foreground">{doc.type}</td><td className="px-5 py-3 text-xs text-foreground">{doc.owner}</td><td className="px-5 py-3 text-xs text-muted-foreground">{doc.date}</td><td className="px-5 py-3 text-xs text-muted-foreground">{doc.size}</td><td className="px-5 py-3"><Pill tone={doc.tone}>{doc.status}</Pill></td></tr>)}</DataTable>{filtered.length===0&&<p className="px-5 py-10 text-center text-sm text-muted-foreground">No documents match this search.</p>}</Panel></div></div>;
}

function ReportsPage() {
  return <div><SectionTitle eyebrow="Business intelligence" title="Reports" description="A clear picture of sales, customer activity, finances, and team productivity." action={<Button variant="outline" onClick={() => toast.info("Report export is available when connected to live data.")}><ArrowDownRight className="size-4"/>Export report</Button>}/><div className="mb-4 flex items-start gap-2 rounded-md border border-info/20 bg-info-subtle p-3 text-xs text-info"><CircleHelp className="mt-0.5 size-4 shrink-0"/><p>All charts below show illustrative demo data. Connect a business data source before using these figures for decisions.</p></div><div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><MetricCard label="Total revenue" value="$86,420" change="14.6%" icon={CreditCard} footnote="October demo"/><MetricCard label="Lead conversion" value="32.6%" change="4.1%" icon={ArrowUpRight} tone="blue" footnote="last 30 days"/><MetricCard label="Customer retention" value="94.8%" change="2.2%" icon={Users} tone="violet" footnote="rolling 90 days"/><MetricCard label="Tasks completed" value="94.2%" change="3.1%" icon={ListChecks} tone="amber" footnote="AI workforce"/></div><div className="mt-4 grid gap-4 xl:grid-cols-2"><Panel className="overflow-hidden"><PanelHeading icon={Activity} label="Revenue performance" note="Monthly revenue trend · sample data" action={<Pill tone="green">+14.6%</Pill>}/><div className="px-5 pb-5 pt-4"><div className="grid h-48 grid-cols-12 items-end gap-2 border-b border-border/70">{[36,46,43,62,56,74,65,82,72,88,80,96].map((height,i)=><div key={i} className="flex h-full items-end"><div className="w-full rounded-t-[3px] bg-primary/80" style={{height:`${height}%`}}/></div>)}</div><div className="mt-2 flex justify-between text-[10px] text-muted-foreground"><span>Jan</span><span>Mar</span><span>May</span><span>Jul</span><span>Sep</span><span>Oct</span></div></div></Panel><Panel className="overflow-hidden"><PanelHeading icon={BriefcaseBusiness} label="Pipeline by stage" note="Opportunity volume · sample data"/><div className="space-y-4 px-5 pb-5 pt-5">{[["Prospecting",78,"bg-info"],["Contacted",60,"bg-primary"],["Qualified",52,"bg-violet"],["Ongoing",40,"bg-info"],["Closing",27,"bg-warning"],["Won",18,"bg-positive"]].map(([label,width,color])=><div key={String(label)}><div className="mb-1 flex justify-between text-[11px]"><span className="text-muted-foreground">{label}</span><span className="text-foreground">{Math.round(Number(width)/6)}</span></div><div className="h-1.5 rounded-full bg-secondary"><div className={`h-full rounded-full ${color}`} style={{width:`${width}%`}}/></div></div>)}</div></Panel><Panel className="overflow-hidden"><PanelHeading icon={Workflow} label="AI workforce productivity" note="Task completion by teammate · sample data"/><div className="space-y-4 px-5 pb-5 pt-5">{aiEmployees.map((employee)=><div key={employee.id} className="flex items-center gap-3"><Avatar name={employee.name} tone={employee.tone} size="sm"/><span className="w-14 text-xs text-foreground">{employee.name}</span><div className="h-1.5 flex-1 rounded-full bg-secondary"><div className="h-full rounded-full bg-primary" style={{width:`${employee.score}%`}}/></div><span className="w-9 text-right text-xs text-muted-foreground">{employee.score}%</span></div>)}</div></Panel><Panel className="overflow-hidden"><PanelHeading icon={Sparkles} label="Marketing channel ROI" note="Attributed engagement · illustrative data"/><div className="grid grid-cols-2 gap-3 p-5">{[["Email", "4.8×", "green"],["LinkedIn", "3.2×", "blue"],["Instagram", "2.6×", "violet"],["Website", "5.1×", "amber"]].map(([label,value,tone])=><div key={label} className="rounded-md border border-border bg-surface-quiet p-3"><p className="text-[10px] text-muted-foreground">{label}</p><p className="mt-2 font-display text-xl font-semibold text-foreground">{value}</p><Pill tone={tone}>{tone==="green"?"Strong":"Tracking"}</Pill></div>)}</div></Panel></div></div>;
}

function IntegrationsPage() {
  const [selected, setSelected] = useState<(typeof portalConfig.integrations)[number] | null>(null);
  const [connection, setConnection] = useState<Record<string, boolean>>({});
  return <div><SectionTitle eyebrow="Connected services" title="Integrations" description="Connect business tools when you’re ready. No services are connected yet." action={<Button variant="outline" onClick={() => toast.info("No connected services to sync.")}><Activity className="size-4"/>Sync status</Button>}/><div className="mb-4 flex items-start gap-2 rounded-md border border-warning/20 bg-warning-subtle p-3 text-xs text-warning"><ShieldCheck className="mt-0.5 size-4 shrink-0"/><p>These are setup options only. No service is connected and no credentials are stored in this demo workspace.</p></div><div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">{portalConfig.integrations.map((integration,i)=><Panel key={integration.name} className="p-4"><div className="flex items-start gap-3"><span className={`grid size-10 shrink-0 place-items-center rounded-md border border-border ${["bg-info-subtle text-info","bg-positive-subtle text-positive","bg-violet-subtle text-violet","bg-warning-subtle text-warning"][i%4]}`}><Link2 className="size-4"/></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="text-sm font-semibold text-foreground">{integration.name}</h2><Pill tone={connection[integration.name]?"green":"neutral"} dot>{connection[integration.name]?"Connected":"Not connected"}</Pill></div><p className="mt-1 text-[10px] text-muted-foreground">{integration.category}</p></div></div><p className="mt-3 min-h-8 text-xs leading-5 text-muted-foreground">{integration.description}</p><div className="mt-3 flex items-center justify-between border-t border-border/70 pt-3"><span className="text-[10px] text-muted-foreground">{connection[integration.name]?"Demo connection only":"No sync activity"}</span><Button variant="outline" size="sm" onClick={() => setSelected(integration)}>Configure <ChevronRight className="size-3"/></Button></div></Panel>)}</div><Dialog open={selected!==null} onOpenChange={(open)=>!open&&setSelected(null)}><DialogContent className="border-border bg-card text-foreground"><DialogHeader><DialogTitle>Configure {selected?.name}</DialogTitle><DialogDescription>{selected?.description}</DialogDescription></DialogHeader><div className="space-y-4"><div className="rounded-md border border-warning/20 bg-warning-subtle p-3 text-xs leading-5 text-warning">This template does not connect external services. Credentials should only be configured through secure server-side settings when integrations are enabled.</div><div className="flex items-center justify-between rounded-md border border-border bg-surface-quiet p-3"><div><p className="text-xs font-medium text-foreground">Demo connection status</p><p className="mt-1 text-[10px] text-muted-foreground">Changes are local to this demo session.</p></div><Switch checked={selected ? Boolean(connection[selected.name]) : false} onCheckedChange={(checked)=>selected&&setConnection({...connection,[selected.name]:checked})}/></div><Button className="w-full" onClick={()=>{toast.info("Real connection requires secure service configuration.");setSelected(null);}}>Save configuration</Button></div></DialogContent></Dialog></div>;
}

function SettingsPage() {
  const [sections, setSections] = useState({ branding: true, approvals: true, audit: true, notifications: true });
  const [tab, setTab] = useState("Company");
  const tabs = ["Company", "Branding", "Users & roles", "AI Workforce", "Notifications", "Security"];
  return <div><SectionTitle eyebrow="Workspace controls" title="Settings" description="Configure this portal for a company, its people, and its AI workforce." action={<Button onClick={() => toast.success("Workspace settings saved in this demo.")}><Check className="size-4"/>Save changes</Button>}/><div className="grid gap-4 lg:grid-cols-[220px_1fr]"><Panel className="h-fit p-3"><nav className="space-y-1">{tabs.map((item)=><Button key={item} variant="ghost" onClick={()=>setTab(item)} className={`h-9 w-full justify-start text-xs ${tab===item?"bg-primary/10 text-primary":"text-muted-foreground"}`}>{item}</Button>)}</nav></Panel><div className="space-y-4"><Panel className="p-5"><div className="mb-5"><h2 className="text-sm font-semibold text-foreground">{tab} configuration</h2><p className="mt-1 text-xs text-muted-foreground">Workspace settings are represented as editable demo values.</p></div>{tab==="Company"&&<div className="grid gap-4 sm:grid-cols-2"><label className="space-y-2 text-xs text-muted-foreground">Company name<Input defaultValue={portalConfig.company.name}/></label><label className="space-y-2 text-xs text-muted-foreground">Workspace description<Input defaultValue={portalConfig.company.descriptor}/></label><label className="space-y-2 text-xs text-muted-foreground sm:col-span-2">Company information<textarea defaultValue="A private workspace for managing business operations and an AI-assisted workforce." className="min-h-24 w-full rounded-md border border-input bg-surface-quiet p-3 text-sm text-foreground outline-none focus-visible:ring-1 focus-visible:ring-ring"/></label></div>}{tab==="Branding"&&<div className="space-y-4"><div className="flex items-center gap-4 rounded-md border border-border bg-surface-quiet p-4"><span className="grid size-12 place-items-center rounded-md bg-primary font-display text-xl font-bold text-primary-foreground">{portalConfig.company.initials}</span><div className="flex-1"><p className="text-xs font-medium text-foreground">Workspace mark</p><p className="mt-1 text-[10px] text-muted-foreground">Logo and favicon are configurable per client portal.</p></div><Button variant="outline" size="sm" onClick={()=>toast.info("Logo uploads are available when file storage is connected.")}>Upload logo</Button></div><div className="grid gap-3 sm:grid-cols-3">{[["Primary",portalConfig.branding.primary],["Secondary",portalConfig.branding.secondary],["Accent",portalConfig.branding.accent]].map(([label,value])=><label key={label} className="rounded-md border border-border bg-surface-quiet p-3"><span className="text-xs text-muted-foreground">{label} colour</span><div className="mt-2 flex items-center gap-2"><span className={`size-5 rounded-sm ${label==="Primary"?"bg-primary":label==="Secondary"?"bg-info":"bg-violet"}`}/><Input defaultValue={value} className="h-8 font-mono text-xs"/></div></label>)}</div></div>}{tab==="Users & roles"&&<div className="space-y-3">{portalConfig.roles.map((role)=><div key={role.name} className="flex flex-wrap items-center gap-3 rounded-md border border-border bg-surface-quiet p-3"><Avatar name={role.name} tone="blue" size="sm"/><span className="flex-1"><span className="block text-xs font-medium text-foreground">{role.name}</span><span className="mt-1 block text-[10px] text-muted-foreground">{role.scope}</span></span><Button variant="outline" size="sm" onClick={()=>toast.info(`${role.name} permissions opened.`)}>Permissions</Button></div>)}</div>}{tab==="AI Workforce"&&<div className="space-y-3">{[{key:"approvals",title:"Require approval for consequential actions",description:"Financial changes, outbound messages, and public content require human sign-off."},{key:"audit",title:"Record AI workforce actions",description:"Keep an audit record of actions, approvals, and escalations."}].map((item)=><div key={item.key} className="flex items-center justify-between gap-4 rounded-md border border-border bg-surface-quiet p-4"><div><p className="text-xs font-medium text-foreground">{item.title}</p><p className="mt-1 text-[10px] leading-4 text-muted-foreground">{item.description}</p></div><Switch checked={sections[item.key as "approvals"|"audit"]} onCheckedChange={(checked)=>setSections({...sections,[item.key]:checked})}/></div>)}</div>}{tab==="Notifications"&&<div className="space-y-3">{[{key:"notifications",title:"Approval notifications",description:"Notify the workspace owner when human review is needed."},{key:"audit",title:"Daily activity summary",description:"Summarize workforce tasks and business activity."}].map((item)=><div key={item.title} className="flex items-center justify-between gap-4 rounded-md border border-border bg-surface-quiet p-4"><div><p className="text-xs font-medium text-foreground">{item.title}</p><p className="mt-1 text-[10px] text-muted-foreground">{item.description}</p></div><Switch checked={sections[item.key as "notifications"|"audit"]} onCheckedChange={(checked)=>setSections({...sections,[item.key]:checked})}/></div>)}</div>}{tab==="Security"&&<div className="space-y-3">{[{title:"Multi-tenant workspace isolation",description:"Prepare each client workspace with its own data access boundaries."},{title:"Credential handling",description:"Integration secrets should be stored securely and never exposed in the interface."},{title:"Human approval controls",description:"AI employees cannot perform consequential external actions without approval."}].map((item)=><div key={item.title} className="flex gap-3 rounded-md border border-border bg-surface-quiet p-4"><ShieldCheck className="mt-0.5 size-4 shrink-0 text-positive"/><div><p className="text-xs font-medium text-foreground">{item.title}</p><p className="mt-1 text-[10px] leading-4 text-muted-foreground">{item.description}</p></div><Pill className="ml-auto">Ready</Pill></div>)}</div>}</Panel><Panel className="overflow-hidden"><PanelHeading icon={Workflow} label="Enabled workspace modules" note="Modules available to this client portal"/><div className="grid gap-2 px-5 pb-5 pt-4 sm:grid-cols-2">{portalConfig.modules.map((module)=>{const Icon=navIcons[module.id as PageId]; return <div key={module.id} className="flex items-center gap-3 rounded-md border border-border bg-surface-quiet p-3"><span className="grid size-8 place-items-center rounded-md bg-info-subtle text-info"><Icon className="size-3.5"/></span><div className="min-w-0 flex-1"><p className="text-xs font-medium text-foreground">{module.label}</p><p className="mt-1 truncate text-[10px] text-muted-foreground">{module.description}</p></div><Switch checked={module.enabled} onCheckedChange={()=>toast.info(`${module.label} module settings are ready to connect.`)}/></div>})}</div></Panel></div></div></div>;
}

function AuditPage({ approvals }: { approvals: typeof approvalsSeed }) {
  const entries = [{actor:"Cathy",action:"Qualified new website lead",module:"Sales",result:"Completed",status:"Recorded",tone:"green",time:"Today, 9:37 am"},{actor:"Jenny",action:"Prepared invoice INV-2048 · $2,400",module:"Accounting",result:"Awaiting approval",status:"Needs review",tone:"amber",time:"Today, 9:28 am"},{actor:"Saun",action:"Resolved onboarding question",module:"Customer support",result:"Completed",status:"Recorded",tone:"green",time:"Today, 9:21 am"},{actor:"Cathy",action:"Prepared October product update",module:"Marketing",result:"Awaiting approval",status:"Needs review",tone:"amber",time:"Today, 9:08 am"},{actor:"John",action:"Assigned weekly campaign review",module:"Operations",result:"Completed",status:"Recorded",tone:"blue",time:"Today, 9:02 am"},{actor:"Alex Morgan",action:"Reviewed workforce permissions",module:"Settings",result:"Updated",status:"User action",tone:"violet",time:"Yesterday, 4:48 pm"}];
  return <div><SectionTitle eyebrow="Accountability" title="Audit Log" description="Chronological record of user and AI workforce activity." action={<Button variant="outline" onClick={()=>toast.info("Audit export is available when a workspace data store is connected.")}><ArrowDownRight className="size-4"/>Export log</Button>}/><div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><MetricCard label="Recorded today" value="24" change="6 new" icon={Activity} footnote="all actors"/><MetricCard label="Awaiting approval" value={approvals.length.toString()} change="Review" icon={ShieldCheck} tone="amber" footnote="human sign-off"/><MetricCard label="AI actions completed" value="18" change="75%" icon={Check} tone="blue" footnote="today"/><MetricCard label="User actions" value="6" change="Today" icon={Users} tone="violet" footnote="workspace owners"/></div><Panel className="mt-4 overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 p-5"><div><h2 className="text-sm font-semibold text-foreground">Activity record</h2><p className="mt-1 text-[11px] text-muted-foreground">This illustrative log shows sample activity and approval states.</p></div><div className="flex gap-2"><Button variant="outline" size="sm" onClick={()=>toast.info("Actor filter opened.")}><Filter className="size-3.5"/>All actors</Button><Button variant="outline" size="sm" onClick={()=>toast.info("Date filter opened.")}><CalendarDays className="size-3.5"/>Last 7 days</Button></div></div><DataTable headers={["Date & time", "Actor", "Action", "Module", "Result", "Approval"]}>{entries.map((entry,i)=><tr key={i}><td className="whitespace-nowrap px-5 py-3 text-xs text-muted-foreground">{entry.time}</td><td className="px-5 py-3"><div className="flex items-center gap-2"><Avatar name={entry.actor} tone={entry.tone} size="sm"/><span className="text-xs font-medium text-foreground">{entry.actor}</span></div></td><td className="px-5 py-3 text-xs text-foreground">{entry.action}</td><td className="px-5 py-3 text-xs text-muted-foreground">{entry.module}</td><td className="px-5 py-3 text-xs text-foreground">{entry.result}</td><td className="px-5 py-3"><Pill tone={entry.tone}>{entry.status}</Pill></td></tr>)}</DataTable></Panel></div>;
}

function EmployeeDialog({ employeeId, onClose }: { employeeId: string | null; onClose: () => void }) {
  const employee = aiEmployees.find((item)=>item.id===employeeId);
  const [tab,setTab]=useState("Overview");
  return <Dialog open={employee!==undefined && employee!==null} onOpenChange={(open)=>!open&&onClose()}><DialogContent className="max-h-[90vh] overflow-y-auto border-border bg-card text-foreground sm:max-w-2xl"><DialogHeader><DialogTitle>AI employee profile</DialogTitle><DialogDescription>Team performance, responsibilities, and activity from the demo workspace.</DialogDescription></DialogHeader>{employee&&<div><div className="flex flex-wrap items-center gap-3 rounded-md border border-border bg-surface-quiet p-4"><Avatar name={employee.name} tone={employee.tone} size="lg"/><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-display text-lg font-semibold">{employee.name}</h3><Pill tone={employee.tone} dot>{employee.status}</Pill></div><p className="mt-1 text-xs text-muted-foreground">{employee.role}</p></div><Button variant="outline" size="sm" onClick={()=>toast.info("Employee configuration is stored in workspace settings.")}><Settings2 className="size-3.5"/>Configure</Button></div><div className="my-4 flex border-b border-border">{["Overview","Activity","Configuration"].map((item)=><Button key={item} variant="ghost" onClick={()=>setTab(item)} className={`h-9 rounded-none border-b-2 px-3 text-xs ${tab===item?"border-primary text-primary":"border-transparent text-muted-foreground"}`}>{item}</Button>)}</div>{tab==="Overview"&&<div className="space-y-4"><div className="grid grid-cols-3 gap-2">{[["Open tasks",employee.tasks],["Completed",employee.completed],["Quality score",`${employee.score}%`]].map(([label,value])=><div key={String(label)} className="rounded-md border border-border bg-surface-quiet p-3"><p className="text-[10px] text-muted-foreground">{label}</p><p className="mt-1 text-lg font-semibold text-foreground">{value}</p></div>)}</div><div><p className="mb-2 text-xs font-semibold text-foreground">Responsibilities</p><ul className="space-y-2">{employee.responsibilities.map((responsibility)=><li key={responsibility} className="flex gap-2 text-xs text-muted-foreground"><Check className="mt-0.5 size-3 shrink-0 text-positive"/>{responsibility}</li>)}</ul></div><div className="rounded-md border border-warning/20 bg-warning-subtle p-3 text-xs leading-5 text-warning"><ShieldCheck className="mr-1 inline size-3.5"/>External and consequential actions remain subject to human approval.</div></div>}{tab==="Activity"&&<ActivityRows items={employee.activity.map((item,i)=>({icon:i===1?ClipboardCheck:Activity,text:item.split(" · ")[0],time:item.split(" · ")[1]??"Today",tone:employee.tone}))}/>} {tab==="Configuration"&&<div className="space-y-3">{[{title:"Allowed autonomous tasks",description:"Review records, classify incoming enquiries, prepare internal summaries."},{title:"Requires human approval",description:"Sending external messages, publishing content, changing finances, commitments."},{title:"Employee prompt & skills",description:"Role: "+employee.role+". Instructions are configurable per client workspace."}].map((item)=><div key={item.title} className="rounded-md border border-border bg-surface-quiet p-4"><p className="text-xs font-medium text-foreground">{item.title}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{item.description}</p></div>)}</div>}</div>}</DialogContent></Dialog>;
}

export function AdminPortal() {
  const [active, setActive] = useState<PageId>("overview");
  const [collapsed,setCollapsed]=useState(false);
  const [mobileOpen,setMobileOpen]=useState(false);
  const [search,setSearch]=useState("");
  const [notificationsOpen,setNotificationsOpen]=useState(false);
  const [approvals,setApprovals]=useState(approvalsSeed);
  const [employeeId,setEmployeeId]=useState<string|null>(null);
  const searchLabel = active === "sales" ? "Search leads..." : active === "customers" ? "Search customers..." : active === "documents" ? "Search documents..." : "Search anything...";
  const filteredApprovals = useMemo(()=>approvals,[approvals]);
  const approve = (id:number)=>{const approved=approvals.find((item)=>item.id===id);setApprovals((current)=>current.filter((item)=>item.id!==id));if(approved)toast.success(`${approved.kind} approved in demo workspace and recorded in the audit log.`);};
  const renderPage = () => {
    if(active==="overview") return <Dashboard approvals={filteredApprovals} onApprove={approve} onEmployee={setEmployeeId} onNavigate={setActive}/>;
    if(active==="workforce") return <WorkforcePage onEmployee={setEmployeeId}/>;
    if(active==="sales") return <SalesPage search={search}/>;
    if(active==="customers") return <CustomersPage search={search}/>;
    if(active==="marketing") return <MarketingPage/>;
    if(active==="accounting") return <AccountingPage/>;
    if(active==="documents") return <DocumentsPage search={search}/>;
    if(active==="reports") return <ReportsPage/>;
    if(active==="integrations") return <IntegrationsPage/>;
    if(active==="settings") return <SettingsPage/>;
    return <AuditPage approvals={filteredApprovals}/>;
  };
  return <div className="flex h-dvh min-h-[620px] w-full overflow-hidden bg-background text-foreground">
    <div className="hidden h-full shrink-0 md:block"><WorkspaceSidebar active={active} onNavigate={(page)=>{setActive(page);setSearch("");}} collapsed={collapsed} onCollapse={()=>setCollapsed((value)=>!value)}/></div>
    {mobileOpen&&<div className="fixed inset-0 z-50 flex md:hidden"><div className="absolute inset-0 bg-background/80 backdrop-blur-sm" onClick={()=>setMobileOpen(false)}/><div className="relative h-full w-[min(300px,84vw)] shadow-2xl"><WorkspaceSidebar active={active} onNavigate={(page)=>{setActive(page);setSearch("");}} collapsed={false} mobile onClose={()=>setMobileOpen(false)}/></div></div>}
    <div className="flex min-w-0 flex-1 flex-col overflow-hidden"><header className="z-20 flex h-[68px] shrink-0 items-center gap-3 border-b border-border/80 bg-background/90 px-3 backdrop-blur-xl sm:px-5"><Button variant="ghost" size="icon" className="md:hidden" onClick={()=>setMobileOpen(true)} aria-label="Open navigation"><Menu className="size-5"/></Button><Button variant="ghost" size="icon" className="hidden size-8 text-muted-foreground md:inline-flex" onClick={()=>setCollapsed(value=>!value)} aria-label={collapsed?"Expand sidebar":"Collapse sidebar"}><ChevronLeft className={`size-4 transition-transform ${collapsed?"rotate-180":""}`}/></Button><div className="hidden h-5 w-px bg-border sm:block"/><div className="min-w-0 flex-1"><div className="hidden items-center gap-2 text-xs sm:flex"><span className="text-muted-foreground">Workspace</span><ChevronRight className="size-3 text-muted-foreground/60"/><span className="font-medium text-foreground">{pageTitles[active]}</span></div><div className="sm:hidden"><p className="truncate text-sm font-semibold text-foreground">{pageTitles[active]}</p></div></div><label className="relative hidden w-full max-w-[250px] md:block"><Search className="absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground"/><Input value={search} onChange={(event)=>setSearch(event.target.value)} placeholder={searchLabel} aria-label="Search workspace" className="h-9 border-border bg-surface-quiet pl-9 pr-12 text-xs placeholder:text-muted-foreground/70"/><span className="absolute right-2 top-1/2 flex -translate-y-1/2 items-center gap-0.5 rounded border border-border px-1 py-0.5 text-[9px] text-muted-foreground"><Command className="size-2.5"/>K</span></label><Button variant="ghost" size="icon" aria-label="Search workspace" className="md:hidden" onClick={()=>toast.info("Search is available on desktop and tablets.")}><Search className="size-4"/></Button><div className="relative"><Button variant="ghost" size="icon" aria-label="Notifications" onClick={()=>setNotificationsOpen(value=>!value)} className="relative"><Bell className="size-[17px]"/>{approvals.length>0&&<span className="absolute right-1.5 top-1.5 size-2 rounded-full border-2 border-background bg-warning"/>}</Button>{notificationsOpen&&<div className="absolute right-0 top-11 z-30 w-[min(320px,88vw)] rounded-lg border border-border bg-popover p-3 shadow-xl"><div className="flex items-center justify-between px-1 pb-2"><span className="text-xs font-semibold text-foreground">Notifications</span><Pill tone="amber">{approvals.length} review</Pill></div>{approvals.length?approvals.map(item=><div key={item.id} className="border-t border-border/70 py-2.5"><p className="text-xs font-medium text-foreground">{item.title}</p><p className="mt-1 text-[10px] text-muted-foreground">{item.detail} · {item.time}</p></div>):<p className="border-t border-border/70 py-4 text-center text-xs text-muted-foreground">You’re all caught up.</p>}</div>}</div><Button variant="ghost" size="icon" aria-label="Open settings" onClick={()=>setActive("settings")}><Settings2 className="size-[17px]"/></Button><span className="mx-0.5 h-5 w-px bg-border"/><Button variant="ghost" className="h-9 gap-2 px-1.5 text-left" onClick={()=>toast.info("Signed in as Alex Morgan · Workspace owner.")}><Avatar name="Alex Morgan" tone="blue" size="sm"/><span className="hidden text-xs font-medium text-foreground lg:inline">Alex Morgan</span><ChevronDown className="hidden size-3 text-muted-foreground lg:block"/></Button></header>
      <main className="relative flex-1 overflow-y-auto"><div className="pointer-events-none absolute right-0 top-0 h-80 w-[min(520px,70vw)] bg-[radial-gradient(ellipse_at_top_right,color-mix(in_oklab,var(--info)_8%,transparent),transparent_65%)]"/><div className="relative mx-auto w-full max-w-[1600px] p-4 sm:p-6 lg:p-8">{renderPage()}<footer className="mt-8 flex flex-wrap items-center justify-between gap-3 border-t border-border/70 py-4 text-[10px] text-muted-foreground"><span>© 2025 {portalConfig.company.name} · Workspace demo</span><span className="flex items-center gap-1.5"><span className="size-1.5 rounded-full bg-positive"/>Sample data · No external services connected</span></footer></div></main>
    </div><EmployeeDialog employeeId={employeeId} onClose={()=>setEmployeeId(null)}/>
  </div>;
}